@namespace Lumeo
@using System.Globalization

@* FlowBackground — a dots / lines / cross grid behind the nodes that pans and zooms with the
   canvas. Place it inside FlowCanvas' ChildContent.

   One <pattern> in flow units (Gap apart), moved and scaled by patternTransform. The engine owns
   patternTransform after mount (it rewrites it with every viewport change, and re-applies it to a
   background that mounts later); .NET only renders it for the first paint. Colour comes from the
   theme (--color-border via lumeo-flow.css) — no hardcoded colours. *@

<svg data-slot="flow-background"
     data-variant="@VariantName"
     aria-hidden="true"
     class="@Cx.Merge("pointer-events-none absolute inset-0 h-full w-full", Class)"
     style="position:absolute;left:0;top:0;width:100%;height:100%;z-index:0;pointer-events:none;"
     @attributes="AdditionalAttributes">
    <defs>
        <pattern id="@_patternId"
                 data-flow-background-pattern
                 patternUnits="userSpaceOnUse"
                 x="0" y="0"
                 width="@F(EffectiveGap)" height="@F(EffectiveGap)"
                 patternTransform="@InitialTransform">
            @switch (Variant)
            {
                case FlowBackgroundVariant.Lines:
                    <path data-flow-background-shape="line"
                          d="@LinesPath"
                          vector-effect="non-scaling-stroke" />
                    break;
                case FlowBackgroundVariant.Cross:
                    <path data-flow-background-shape="line"
                          d="@CrossPath"
                          vector-effect="non-scaling-stroke" />
                    break;
                default:
                    <circle data-flow-background-shape="dot"
                            cx="@F(EffectiveGap / 2)" cy="@F(EffectiveGap / 2)"
                            r="@F(EffectiveSize)" />
                    break;
            }
        </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#@_patternId)" />
</svg>

@code {
    [CascadingParameter] private FlowCanvas.FlowCanvasContext? Context { get; set; }

    /// <summary>What the grid draws.</summary>
    [Parameter] public FlowBackgroundVariant Variant { get; set; } = FlowBackgroundVariant.Dots;

    /// <summary>Grid spacing in flow units.</summary>
    [Parameter] public double Gap { get; set; } = 20;

    /// <summary>Dot radius (dots) or half the arm length (cross), in flow units. Ignored for lines.</summary>
    [Parameter] public double Size { get; set; } = 1;

    /// <summary>Additional CSS classes merged onto the background <c>&lt;svg&gt;</c>.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the background <c>&lt;svg&gt;</c>.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private readonly string _patternId = "lumeo-flow-bg-" + Guid.NewGuid().ToString("N")[..10];

    private double EffectiveGap => Gap > 0 ? Gap : 20;
    private double EffectiveSize => Size > 0 ? Size : 1;

    private string VariantName => Variant switch
    {
        FlowBackgroundVariant.Lines => "lines",
        FlowBackgroundVariant.Cross => "cross",
        _ => "dots",
    };

    private string InitialTransform
    {
        get
        {
            var v = Context?.InitialViewport ?? new FlowViewport(0, 0, 1);
            return "translate(" + FlowCanvas.R(v.X) + "," + FlowCanvas.R(v.Y) + ") scale(" + FlowCanvas.R(v.Zoom) + ")";
        }
    }

    private string LinesPath
    {
        get
        {
            var g = F(EffectiveGap);
            return "M0,0 L" + g + ",0 M0,0 L0," + g;
        }
    }

    private string CrossPath
    {
        get
        {
            var c = EffectiveGap / 2;
            var s = Math.Min(EffectiveSize * 3, c);
            return "M" + F(c - s) + "," + F(c) + " L" + F(c + s) + "," + F(c)
                 + " M" + F(c) + "," + F(c - s) + " L" + F(c) + "," + F(c + s);
        }
    }

    private static string F(double v) => FlowGeometry.Fmt(v);
}

@namespace Lumeo
@implements IAsyncDisposable
@using System.ComponentModel
@using System.Globalization
@inject Lumeo.Services.IComponentInteropService Interop
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* FlowCanvas — a node/flow editor surface (Lumeo.Flow, spec: src/Lumeo.Flow/DESIGN.md).

   Rendering: the root carries role="application"; the pane clips and receives every gesture;
   inside it one viewport layer (transform: translate + scale) holds the SVG edge layer and the
   absolutely positioned node hosts, so nodes and edges live in FLOW coordinates and pan/zoom is a
   single transform. ChildContent (FlowBackground, FlowControls, ...) renders beside the viewport
   layer inside the pane.

   Ownership: after the first render the viewport transform belongs to flow.js. .NET changes it
   only by stamping data-flow-viewport="x|y|zoom|id" on the pane; the engine's MutationObserver
   applies the stamp in the same frame the render lands. Pan, wheel zoom and node drag run in JS
   without a render per frame; .NET hears about them through the JSInvokable members below. *@

<div data-slot="flow-canvas"
     role="application"
     aria-label="@L["Flow.CanvasLabel"]"
     class="@RootClass"
     style="@RootStyle"
     data-flow-fit-pending="@(FitViewOnInit ? "" : null)"
     data-readonly="@(Readonly ? "" : null)"
     @attributes="AdditionalAttributes">
    <div @ref="_paneRef"
         data-slot="flow-pane"
         data-flow-viewport="@ViewportStamp"
         data-flow-generation="@_state.Generation.ToString(CultureInfo.InvariantCulture)"
         style="position:relative;width:100%;height:100%;overflow:hidden;touch-action:none;">
        <CascadingValue Value="_context" IsFixed="false">
            <div data-slot="flow-viewport" style="@_viewportLayerStyle">
                <FlowEdgeLayer />
                <div data-slot="flow-nodes">
                    @foreach (var node in _nodes)
                    {
                        <FlowNodeHost @key="node.Id" Node="node" />
                    }
                </div>
            </div>
            @ChildContent
        </CascadingValue>
    </div>
</div>

@code {
    // ── Data ─────────────────────────────────────────────────────────────

    /// <summary>The nodes to render. Two-way bindable (<c>@bind-Nodes</c>): every committed drag or keyboard move emits a new list through <see cref="NodesChanged"/>. Without a binding the canvas keeps its own copy until you pass a different list.</summary>
    [Parameter] public IReadOnlyList<FlowNode>? Nodes { get; set; }

    /// <summary>Raised with the new node list after a committed drag or keyboard move.</summary>
    [Parameter] public EventCallback<IReadOnlyList<FlowNode>> NodesChanged { get; set; }

    /// <summary>The edges to draw between nodes. Edges whose source or target node is missing are skipped.</summary>
    [Parameter] public IReadOnlyList<FlowEdge>? Edges { get; set; }

    /// <summary>The pan/zoom state. Two-way bindable (<c>@bind-Viewport</c>). Setting a new value moves the canvas; the canvas reports user pans and zooms back through <see cref="ViewportChanged"/>. A zoom of 0 or less means "not set" (the canvas starts at 0,0 and 100%).</summary>
    [Parameter] public FlowViewport Viewport { get; set; } = new(0, 0, 1);

    /// <summary>Raised when the viewport changes — at most once per animation frame while a pan or wheel zoom is running, once more when it ends, and after every imperative change (<see cref="FitViewAsync"/>, <see cref="ZoomInAsync"/>, ...).</summary>
    [Parameter] public EventCallback<FlowViewport> ViewportChanged { get; set; }

    /// <summary>Renders each node's content. The canvas wraps it in a positioned, focusable host. Without a template a node renders a small card with its <c>Data</c> (or <c>Id</c>).</summary>
    [Parameter] public RenderFragment<FlowNodeContext>? NodeTemplate { get; set; }

    /// <summary>Overlays rendered inside the pane: <see cref="FlowBackground"/>, <see cref="FlowControls"/>, your own panels.</summary>
    [Parameter] public RenderFragment? ChildContent { get; set; }

    // ── Layout and behaviour ─────────────────────────────────────────────

    /// <summary>CSS height of the canvas.</summary>
    [Parameter] public string Height { get; set; } = "500px";

    /// <summary>Smallest zoom a gesture or method may reach.</summary>
    [Parameter] public double MinZoom { get; set; } = 0.25;

    /// <summary>Largest zoom a gesture or method may reach.</summary>
    [Parameter] public double MaxZoom { get; set; } = 2;

    /// <summary>Fits every node into view once the canvas has mounted and measured its nodes (the nodes stay invisible until then, so the un-fitted frame never shows).</summary>
    [Parameter] public bool FitViewOnInit { get; set; } = true;

    /// <summary>Breathing room for fit-view, as a fraction of the nodes' bounds (0.1 = 10%).</summary>
    [Parameter] public double FitViewPadding { get; set; } = 0.1;

    /// <summary>Snaps dragged and keyboard-moved nodes to <see cref="SnapGrid"/>.</summary>
    [Parameter] public bool SnapToGrid { get; set; }

    /// <summary>The snap grid in flow units (X, Y).</summary>
    [Parameter] public (double X, double Y) SnapGrid { get; set; } = (16, 16);

    /// <summary>Nodes can be moved by dragging or with the arrow keys.</summary>
    [Parameter] public bool NodesDraggable { get; set; } = true;

    /// <summary>Dragging the empty background pans the canvas. Holding Space pans from anywhere either way.</summary>
    [Parameter] public bool PanOnDrag { get; set; } = true;

    /// <summary>The mouse wheel zooms, anchored on the pointer (a plain wheel — no modifier — like React Flow; the page does not scroll while the pointer is over the canvas).</summary>
    [Parameter] public bool ZoomOnScroll { get; set; } = true;

    /// <summary>Turns every editing gesture off (node drag and keyboard move now; connect and delete in later phases). Pan, zoom, selection and click events keep working.</summary>
    [Parameter] public bool Readonly { get; set; }

    // ── Events ───────────────────────────────────────────────────────────

    /// <summary>A node was clicked (not raised for the click that ends a drag).</summary>
    [Parameter] public EventCallback<FlowNode> OnNodeClick { get; set; }

    /// <summary>A node was double-clicked.</summary>
    [Parameter] public EventCallback<FlowNode> OnNodeDoubleClick { get; set; }

    /// <summary>A node was right-clicked. The browser menu is suppressed while this has a handler.</summary>
    [Parameter] public EventCallback<FlowNodeContextMenuEventArgs> OnNodeContextMenu { get; set; }

    /// <summary>The empty background was clicked (not dragged); the point is in flow coordinates.</summary>
    [Parameter] public EventCallback<FlowPoint> OnPaneClick { get; set; }

    /// <summary>A drag (or arrow-key move) was committed; one entry per moved node. Raised after <see cref="NodesChanged"/>.</summary>
    [Parameter] public EventCallback<IReadOnlyList<FlowNodeChange>> OnNodeDragStop { get; set; }

    /// <summary>Additional CSS classes merged onto the root element.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    /// <summary>
    /// What the canvas cascades to <see cref="FlowBackground"/>, <see cref="FlowControls"/> and its own
    /// node/edge layers. Re-created on every render (cascaded with <c>IsFixed="false"</c>).
    /// </summary>
    /// <param name="Canvas">The owning canvas.</param>
    /// <param name="Viewport">The latest known viewport.</param>
    /// <param name="InitialViewport">The viewport of the first render — what server-rendered transforms use; the engine owns them after mount.</param>
    /// <param name="Locked">The lock toggle is on (no node drag).</param>
    /// <param name="MinZoom">The canvas' <c>MinZoom</c>.</param>
    /// <param name="MaxZoom">The canvas' <c>MaxZoom</c>.</param>
    public record FlowCanvasContext(FlowCanvas Canvas, FlowViewport Viewport, FlowViewport InitialViewport, bool Locked, double MinZoom, double MaxZoom);

    // ── State ────────────────────────────────────────────────────────────

    internal readonly FlowState _state = new();
    private ElementReference _paneRef;
    private DotNetObjectReference<FlowCanvas>? _selfRef;
    private IReadOnlyList<FlowNode> _nodes = Array.Empty<FlowNode>();
    private IReadOnlyList<FlowNode>? _lastNodesParam;
    private readonly List<IReadOnlyList<FlowNode>> _recentEmitted = new();
    private FlowViewport _lastViewportParam;
    private FlowViewport _initialViewport = new(0, 0, 1);
    private string _viewportLayerStyle = "";
    private FlowCanvasContext _context = default!;
    private bool _initialized;
    private bool _locked;
    private bool _registered;
    private bool _disposed;
    private FlowEngineOptions? _lastOptions;

    /// <summary>The options bag pushed to flow.js. A record, so "changed?" is structural equality.</summary>
    internal sealed record FlowEngineOptions(
        double MinZoom, double MaxZoom, bool SnapToGrid, double SnapX, double SnapY,
        bool NodesDraggable, bool PanOnDrag, bool ZoomOnScroll, bool Readonly,
        bool FitViewOnInit, double FitViewPadding)
    {
        /// <summary>Serialised as <c>snap</c>: <c>[gx, gy]</c> or null.</summary>
        public double[]? Snap => SnapToGrid ? new[] { SnapX, SnapY } : null;
    }

    /// <summary>The viewport as .NET last knows it (engine reports and imperative changes).</summary>
    public FlowViewport CurrentViewport => _state.Viewport;

    /// <summary>The nodes as currently rendered (the bound list, or the canvas' own copy).</summary>
    public IReadOnlyList<FlowNode> CurrentNodes => _nodes;

    internal bool Locked => _locked;
    internal bool CanMoveNodes => NodesDraggable && !Readonly && !_locked;

    private string RootClass => Cx.Merge(
        "relative block w-full overflow-hidden rounded-lg border border-border bg-background text-foreground",
        Class);

    private string RootStyle => "height:" + Height + ";";

    private string ViewportStamp
    {
        get
        {
            var v = _state.StampedViewport;
            return R(v.X) + "|" + R(v.Y) + "|" + R(v.Zoom) + "|" + _state.StampId.ToString(CultureInfo.InvariantCulture);
        }
    }

    internal static string R(double value) => (value == 0 ? 0 : value).ToString("R", CultureInfo.InvariantCulture);

    private static string LayerStyle(FlowViewport v)
        => "position:absolute;left:0;top:0;z-index:1;transform-origin:0 0;transform:translate("
           + R(v.X) + "px, " + R(v.Y) + "px) scale(" + R(v.Zoom) + ");";

    private FlowViewport Sanitize(FlowViewport v)
    {
        if (!(v.Zoom > 0) || !double.IsFinite(v.Zoom) || !double.IsFinite(v.X) || !double.IsFinite(v.Y)) return new(0, 0, 1);
        return v with { Zoom = FlowGeometry.ClampZoom(v.Zoom, MinZoom, MaxZoom) };
    }

    protected override void OnParametersSet()
    {
        // Nodes: a list we emitted ourselves coming back through @bind-Nodes is an echo; anything
        // else replaces the state from outside and bumps the generation, so a drag that started
        // before it can never commit over it.
        if (!_initialized || !ReferenceEquals(Nodes, _lastNodesParam))
        {
            _lastNodesParam = Nodes;
            var incoming = Nodes ?? Array.Empty<FlowNode>();
            var emittedIndex = _recentEmitted.FindIndex(l => ReferenceEquals(l, Nodes));
            if (!_initialized)
            {
                _nodes = incoming;
            }
            else if (emittedIndex >= 0)
            {
                // Our own list. Only the latest one is current; an older echo (two commits in quick
                // succession, the parent catching up) must not roll the canvas back.
                if (emittedIndex == _recentEmitted.Count - 1) _nodes = incoming;
            }
            else
            {
                _nodes = incoming;
                _state.BumpGeneration();
            }
            _state.ForgetMissing(_nodes);
            if (_state.SelectedNodeIds.Count > 0)
            {
                var live = new HashSet<string>(_nodes.Select(n => n.Id), StringComparer.Ordinal);
                _state.SelectedNodeIds.RemoveWhere(id => !live.Contains(id));
            }
        }

        // Viewport: the first value seeds the state and the server-rendered transform; later values
        // are instructions unless they are an echo of what the engine reported.
        if (!_initialized)
        {
            _initialViewport = Sanitize(Viewport);
            _state.Initialize(_initialViewport);
            _viewportLayerStyle = LayerStyle(_initialViewport);
            _lastViewportParam = Viewport;
        }
        else if (Viewport != _lastViewportParam)
        {
            _lastViewportParam = Viewport;
            var v = Sanitize(Viewport);
            if (!_state.IsEcho(Viewport) && !_state.IsEcho(v)) _state.Stamp(v);
        }

        _initialized = true;
        RefreshContext();
    }

    private void RefreshContext()
        => _context = new FlowCanvasContext(this, _state.Viewport, _initialViewport, _locked, MinZoom, MaxZoom);

    private FlowEngineOptions BuildOptions() => new(
        MinZoom, MaxZoom, SnapToGrid, SnapGrid.X, SnapGrid.Y,
        CanMoveNodes, PanOnDrag, ZoomOnScroll, Readonly,
        FitViewOnInit, FitViewPadding);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        var options = BuildOptions();
        if (firstRender)
        {
            _selfRef ??= DotNetObjectReference.Create(this);
            // Claimed BEFORE the await (memory: guard before the await) — a dispose that lands while
            // the register call is in flight sees it and unregisters; the re-check after the await
            // below closes the other half of that race.
            _registered = true;
            _lastOptions = options;
            try
            {
                await Interop.FlowRegisterCanvasAsync(_paneRef, _selfRef, options);
            }
            catch (JSDisconnectedException)
            {
            }
            catch (Exception)
            {
                // A custom interop service that throws: the canvas degrades to a static render
                // instead of taking the page down. A later render does not retry — registration
                // is a mount-time contract.
                _registered = false;
            }
            if (_disposed)
            {
                try { await Interop.FlowUnregisterCanvasAsync(_paneRef); }
                catch (JSDisconnectedException) { }
            }
            return;
        }

        if (_registered && !_disposed && options != _lastOptions)
        {
            _lastOptions = options;
            try { await Interop.FlowUpdateOptionsAsync(_paneRef, options); }
            catch (JSDisconnectedException) { }
        }
    }

    // ── Node rendering helpers (used by FlowNodeHost / FlowEdgeLayer) ────

    internal bool IsSelected(string id) => _state.SelectedNodeIds.Contains(id);
    internal bool IsDragging(string id) => _state.DraggingNodeIds.Contains(id);
    internal bool CanDrag(FlowNode node) => CanMoveNodes && node.Draggable;
    internal bool HasContextMenuHandler => OnNodeContextMenu.HasDelegate;

    internal RenderFragment RenderNodeContent(FlowNodeContext context)
        => NodeTemplate is not null ? NodeTemplate(context) : DefaultNodeContent(context);

    private static RenderFragment DefaultNodeContent(FlowNodeContext context) => builder =>
    {
        builder.OpenElement(0, "div");
        builder.AddAttribute(1, "class", "rounded-md border border-border bg-card px-3 py-2 text-sm text-card-foreground shadow-sm");
        builder.AddContent(2, context.Node.Data?.ToString() ?? context.Node.Id);
        builder.CloseElement();
    };

    internal IEnumerable<(FlowEdge Edge, FlowEdgePath Path)> RenderableEdges()
    {
        if (Edges is null || Edges.Count == 0) yield break;
        var byId = new Dictionary<string, FlowNode>(StringComparer.Ordinal);
        foreach (var n in _nodes) byId[n.Id] = n;
        foreach (var edge in Edges)
        {
            if (edge is null) continue;
            if (!byId.TryGetValue(edge.Source, out var s) || !byId.TryGetValue(edge.Target, out var t)) continue;
            var (sp, spos) = _state.GetAnchor(s, edge.SourceHandle, FlowHandleType.Source);
            var (tp, tpos) = _state.GetAnchor(t, edge.TargetHandle, FlowHandleType.Target);
            yield return (edge, FlowGeometry.GetEdgePath(edge.Type, sp.X, sp.Y, spos, tp.X, tp.Y, tpos));
        }
    }

    // ── Node events (from FlowNodeHost) ──────────────────────────────────

    internal async Task HandleNodeClickAsync(FlowNode node)
    {
        if (node.Selectable && !(_state.SelectedNodeIds.Count == 1 && _state.SelectedNodeIds.Contains(node.Id)))
        {
            _state.SelectedNodeIds.Clear();
            _state.SelectedNodeIds.Add(node.Id);
            StateHasChanged();
        }
        if (OnNodeClick.HasDelegate) await OnNodeClick.InvokeAsync(node);
    }

    internal Task HandleNodeDoubleClickAsync(FlowNode node)
        => OnNodeDoubleClick.HasDelegate ? OnNodeDoubleClick.InvokeAsync(node) : Task.CompletedTask;

    internal Task HandleNodeContextMenuAsync(FlowNode node, MouseEventArgs e)
        => OnNodeContextMenu.HasDelegate
            ? OnNodeContextMenu.InvokeAsync(new FlowNodeContextMenuEventArgs(node, e.ClientX, e.ClientY))
            : Task.CompletedTask;

    internal async Task HandleNodeKeyDownAsync(FlowNode node, KeyboardEventArgs e)
    {
        switch (e.Key)
        {
            case "Escape":
                if (_state.SelectedNodeIds.Count > 0)
                {
                    _state.SelectedNodeIds.Clear();
                    StateHasChanged();
                }
                return;
            case "ArrowLeft":
            case "ArrowRight":
            case "ArrowUp":
            case "ArrowDown":
                await MoveByKeyboardAsync(node, e.Key, e.ShiftKey);
                return;
        }
    }

    private async Task MoveByKeyboardAsync(FlowNode node, string key, bool shift)
    {
        if (!CanMoveNodes) return;
        var current = _nodes.FirstOrDefault(n => n.Id == node.Id);
        if (current is null || !current.Draggable) return;

        var stepX = SnapToGrid && SnapGrid.X > 0 ? SnapGrid.X : 1;
        var stepY = SnapToGrid && SnapGrid.Y > 0 ? SnapGrid.Y : 1;
        if (shift) { stepX *= 10; stepY *= 10; }
        var (dx, dy) = key switch
        {
            "ArrowLeft" => (-stepX, 0d),
            "ArrowRight" => (stepX, 0d),
            "ArrowUp" => (0d, -stepY),
            _ => (0d, stepY),
        };

        // The focused node, plus the rest of the selection when the focused node is part of it.
        var moving = _state.SelectedNodeIds.Contains(current.Id)
            ? new HashSet<string>(_state.SelectedNodeIds, StringComparer.Ordinal)
            : new HashSet<string>(StringComparer.Ordinal) { current.Id };

        var changes = new List<FlowNodeChange>();
        var next = new List<FlowNode>(_nodes.Count);
        foreach (var n in _nodes)
        {
            if (moving.Contains(n.Id) && n.Draggable)
            {
                var x = n.X + dx;
                var y = n.Y + dy;
                if (SnapToGrid)
                {
                    x = FlowGeometry.Snap(x, SnapGrid.X);
                    y = FlowGeometry.Snap(y, SnapGrid.Y);
                }
                next.Add(n with { X = x, Y = y });
                changes.Add(new FlowNodeChange(n.Id, x, y));
            }
            else
            {
                next.Add(n);
            }
        }
        if (changes.Count == 0) return;
        await EmitNodesAsync(next);
        if (OnNodeDragStop.HasDelegate) await OnNodeDragStop.InvokeAsync(changes);
    }

    private Task EmitNodesAsync(List<FlowNode> next)
    {
        // State first, synchronously — anything that arrives while NodesChanged is awaited (a
        // second commit, a keyboard move) builds on this list, not on the one it replaced.
        _nodes = next;
        _recentEmitted.Add(next);
        if (_recentEmitted.Count > 8) _recentEmitted.RemoveAt(0);
        StateHasChanged();
        return NodesChanged.HasDelegate ? NodesChanged.InvokeAsync(next) : Task.CompletedTask;
    }

    // ── Imperative API ───────────────────────────────────────────────────

    /// <summary>Fits every node into view. <paramref name="padding"/> defaults to <see cref="FitViewPadding"/>.</summary>
    public async Task FitViewAsync(double? padding = null)
    {
        var pad = padding ?? FitViewPadding;
        if (_nodes.Count == 0) return;
        if (_state.PaneWidth > 0 && _state.PaneHeight > 0 && _state.AllSized(_nodes)
            && _state.ComputeFit(_nodes, pad, MinZoom, MaxZoom) is { } vp)
        {
            await SetViewportCoreAsync(vp);
            return;
        }
        // Some node has never been measured: let the engine measure the DOM and fit (it reports back).
        if (_registered && !_disposed)
        {
            try { await Interop.FlowFitViewAsync(_paneRef, pad, MinZoom, MaxZoom); }
            catch (JSDisconnectedException) { }
        }
    }

    /// <summary>Zooms to <paramref name="zoom"/> (clamped to the zoom limits), keeping the pane centre fixed.</summary>
    public async Task ZoomToAsync(double zoom)
    {
        var current = await LiveViewportAsync();
        var z = FlowGeometry.ClampZoom(zoom, MinZoom, MaxZoom);
        await SetViewportCoreAsync(FlowGeometry.ZoomAt(current, z, _state.PaneWidth / 2, _state.PaneHeight / 2));
    }

    /// <summary>Zooms in one step (×1.2) around the pane centre.</summary>
    public async Task ZoomInAsync() => await ZoomToAsync((await LiveViewportAsync()).Zoom * FlowGeometry.ZoomStep);

    /// <summary>Zooms out one step (÷1.2) around the pane centre.</summary>
    public async Task ZoomOutAsync() => await ZoomToAsync((await LiveViewportAsync()).Zoom / FlowGeometry.ZoomStep);

    /// <summary>Centres the pane on flow point (<paramref name="x"/>, <paramref name="y"/>), optionally at a new zoom.</summary>
    public async Task SetCenterAsync(double x, double y, double? zoom = null)
    {
        var current = await LiveViewportAsync();
        var z = FlowGeometry.ClampZoom(zoom ?? current.Zoom, MinZoom, MaxZoom);
        await SetViewportCoreAsync(FlowGeometry.CenterOn(x, y, z, _state.PaneWidth, _state.PaneHeight));
    }

    /// <summary>Moves the canvas to <paramref name="viewport"/> (zoom clamped to the limits).</summary>
    public Task SetViewportAsync(FlowViewport viewport) => SetViewportCoreAsync(Sanitize(viewport));

    /// <summary>Pane-local pixels (relative to the canvas pane's top-left corner, e.g. <c>MouseEventArgs.OffsetX</c> on the pane) → flow coordinates, using the latest known viewport.</summary>
    public FlowPoint ScreenToFlow(double x, double y) => FlowGeometry.ScreenToFlow(x, y, _state.Viewport);

    /// <summary>Flow coordinates → pane-local pixels, using the latest known viewport.</summary>
    public FlowPoint FlowToScreen(double x, double y) => FlowGeometry.FlowToScreen(x, y, _state.Viewport);

    internal async Task SetLockedAsync(bool locked)
    {
        if (_locked == locked) return;
        _locked = locked;
        RefreshContext();
        await InvokeAsync(StateHasChanged);
    }

    private async Task<FlowViewport> LiveViewportAsync()
    {
        if (_registered && !_disposed)
        {
            try
            {
                var live = await Interop.FlowGetViewportAsync(_paneRef);
                if (live is { Length: 3 } && live[2] > 0) return new FlowViewport(live[0], live[1], live[2]);
            }
            catch (JSDisconnectedException) { }
        }
        return _state.Viewport;
    }

    private async Task SetViewportCoreAsync(FlowViewport viewport)
    {
        _state.Stamp(viewport);
        RefreshContext();
        await InvokeAsync(StateHasChanged);
        if (ViewportChanged.HasDelegate) await InvokeAsync(() => ViewportChanged.InvokeAsync(viewport));
    }

    // ── Engine callbacks (flow.js) ───────────────────────────────────────

    /// <summary>Engine callback: a node drag ended. Applies the positions unless the drag started under an older node list (<paramref name="generation"/>) or editing is off; returns whether it did. Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public async Task<bool> CommitNodeDrag(FlowNodeChange[] changes, int generation)
    {
        var hadDragging = _state.DraggingNodeIds.Count > 0;
        _state.DraggingNodeIds.Clear();
        if (changes is null || changes.Length == 0 || !CanMoveNodes || generation != _state.Generation)
        {
            if (hadDragging) StateHasChanged();
            return false;
        }

        var map = new Dictionary<string, FlowNodeChange>(StringComparer.Ordinal);
        foreach (var c in changes)
        {
            if (c is null || string.IsNullOrEmpty(c.Id) || !double.IsFinite(c.X) || !double.IsFinite(c.Y)) continue;
            map[c.Id] = c;
        }

        var applied = new List<FlowNodeChange>();
        var next = new List<FlowNode>(_nodes.Count);
        foreach (var n in _nodes)
        {
            if (n.Draggable && map.TryGetValue(n.Id, out var c))
            {
                next.Add(n with { X = c.X, Y = c.Y });
                applied.Add(new FlowNodeChange(n.Id, c.X, c.Y));
            }
            else
            {
                next.Add(n);
            }
        }
        if (applied.Count == 0)
        {
            if (hadDragging) StateHasChanged();
            return false;
        }

        await EmitNodesAsync(next);
        if (OnNodeDragStop.HasDelegate) await OnNodeDragStop.InvokeAsync(applied);
        return true;
    }

    /// <summary>Engine callback: a drag passed its threshold. Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public void NodeDragStart(string[] ids)
    {
        _state.DraggingNodeIds.Clear();
        if (ids is not null) foreach (var id in ids) if (!string.IsNullOrEmpty(id)) _state.DraggingNodeIds.Add(id);
        StateHasChanged();
    }

    /// <summary>Engine callback: a drag was cancelled (Escape, pointer cancel). Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public void NodeDragCancelled()
    {
        if (_state.DraggingNodeIds.Count == 0) return;
        _state.DraggingNodeIds.Clear();
        StateHasChanged();
    }

    /// <summary>Engine callback: the viewport moved (pan, wheel zoom, engine fit). Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public async Task OnViewportChanged(double x, double y, double zoom, bool final)
    {
        if (!double.IsFinite(x) || !double.IsFinite(y) || !(zoom > 0)) return;
        var viewport = new FlowViewport(x, y, zoom);
        _state.Report(viewport);
        if (ViewportChanged.HasDelegate) await ViewportChanged.InvokeAsync(viewport);
        if (final)
        {
            // Once per gesture: refresh what depends on the zoom (the controls' limits).
            RefreshContext();
            StateHasChanged();
        }
    }

    /// <summary>Engine callback: node sizes / handle offsets were measured. Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public void NodesMeasured(FlowNodeMeasurement[] measurements)
    {
        if (measurements is null) return;
        if (_state.ApplyMeasurements(measurements)) StateHasChanged();
    }

    /// <summary>Engine callback: the pane was resized. Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public void PaneResized(double width, double height) => _state.SetPaneSize(width, height);

    /// <summary>Engine callback: the background was clicked at a flow point. Not meant for application code.</summary>
    [JSInvokable, EditorBrowsable(EditorBrowsableState.Never)]
    public async Task PaneClicked(double x, double y)
    {
        if (_state.SelectedNodeIds.Count > 0)
        {
            _state.SelectedNodeIds.Clear();
            StateHasChanged();
        }
        if (OnPaneClick.HasDelegate) await OnPaneClick.InvokeAsync(new FlowPoint(x, y));
    }

    /// <inheritdoc />
    public async ValueTask DisposeAsync()
    {
        _disposed = true;
        if (_registered)
        {
            try { await Interop.FlowUnregisterCanvasAsync(_paneRef); }
            catch (JSDisconnectedException) { }
        }
        _selfRef?.Dispose();
    }
}

@namespace Lumeo
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* FlowControls — zoom in / zoom out / fit view / lock, stacked in a corner of the canvas. Place it
   inside FlowCanvas' ChildContent. Built from Lumeo Buttons (Outline, icon size); any ChildContent
   is appended as extra buttons. data-flow-overlay keeps the canvas engine from treating a press
   here as a pan. *@

<div data-slot="flow-controls"
     data-flow-overlay
     role="toolbar"
     aria-label="@L["Flow.Controls"]"
     aria-orientation="@(Horizontal ? "horizontal" : "vertical")"
     class="@RootClass"
     style="position:absolute;z-index:5;"
     @attributes="AdditionalAttributes">
    @if (ShowZoom)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.ZoomIn"]" title="@L["Flow.ZoomIn"]"
                Disabled="@(!CanZoomIn)" OnClick="ZoomInAsync">
            <SvgGlyph Svg="@(LumeoIcons.Plus)" class="size-4" />
        </Button>
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.ZoomOut"]" title="@L["Flow.ZoomOut"]"
                Disabled="@(!CanZoomOut)" OnClick="ZoomOutAsync">
            <SvgGlyph Svg="@(LumeoIcons.Minus)" class="size-4" />
        </Button>
    }
    @if (ShowFitView)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon" Class="size-8 bg-card"
                aria-label="@L["Flow.FitView"]" title="@L["Flow.FitView"]"
                OnClick="FitViewAsync">
            <SvgGlyph Svg="@(LumeoIcons.Maximize2)" class="size-4" />
        </Button>
    }
    @if (ShowLock)
    {
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Icon"
                Class="@Cx.Merge("size-8 bg-card", Cx.When(Locked, "bg-accent text-accent-foreground"))"
                aria-label="@L["Flow.Lock"]" title="@L["Flow.Lock"]"
                aria-pressed="@(Locked ? "true" : "false")"
                OnClick="ToggleLockAsync">
            <SvgGlyph Svg="@(LumeoIcons.Lock)" class="size-4" />
        </Button>
    }
    @ChildContent
</div>

@code {
    [CascadingParameter] private FlowCanvas.FlowCanvasContext? Context { get; set; }

    /// <summary>Where the controls sit inside the canvas.</summary>
    public enum ControlsPosition { TopLeft, TopRight, BottomLeft, BottomRight }

    /// <summary>The corner the controls sit in.</summary>
    [Parameter] public ControlsPosition Position { get; set; } = ControlsPosition.BottomLeft;

    /// <summary>Lays the buttons out in a row instead of a column.</summary>
    [Parameter] public bool Horizontal { get; set; }

    /// <summary>Shows the zoom in / zoom out buttons.</summary>
    [Parameter] public bool ShowZoom { get; set; } = true;

    /// <summary>Shows the fit-view button.</summary>
    [Parameter] public bool ShowFitView { get; set; } = true;

    /// <summary>Shows the lock toggle (locked = nodes cannot be moved; pan and zoom still work).</summary>
    [Parameter] public bool ShowLock { get; set; } = true;

    /// <summary>Extra buttons appended after the built-in ones.</summary>
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes merged onto the toolbar.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the toolbar.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private bool Locked => Context?.Locked == true;
    private double Zoom => Context?.Viewport.Zoom ?? 1;
    private bool CanZoomIn => Context is null || Zoom < Context.MaxZoom - 1e-9;
    private bool CanZoomOut => Context is null || Zoom > Context.MinZoom + 1e-9;

    private string RootClass => Cx.Merge(
        "flex gap-1 rounded-md",
        Horizontal ? "flex-row" : "flex-col",
        Position switch
        {
            ControlsPosition.TopLeft => "left-3 top-3",
            ControlsPosition.TopRight => "right-3 top-3",
            ControlsPosition.BottomRight => "right-3 bottom-3",
            _ => "left-3 bottom-3",
        },
        Class);

    private Task ZoomInAsync() => Context?.Canvas.ZoomInAsync() ?? Task.CompletedTask;
    private Task ZoomOutAsync() => Context?.Canvas.ZoomOutAsync() ?? Task.CompletedTask;
    private Task FitViewAsync() => Context?.Canvas.FitViewAsync() ?? Task.CompletedTask;
    private Task ToggleLockAsync() => Context?.Canvas.SetLockedAsync(!Locked) ?? Task.CompletedTask;
}

@namespace Lumeo
@using System.ComponentModel
@attribute [EditorBrowsable(EditorBrowsableState.Never)]

@* FlowEdgeLayer — one <path> per edge, in flow coordinates, inside FlowCanvas' viewport layer.
   Rendered by FlowCanvas; not meant to be used directly.

   The <svg> is zero-sized with overflow: visible so it never intercepts pointer events or affects
   layout; paths are drawn from FlowGeometry. While a node is dragged the engine rewrites the `d`
   of every connected path with its JS port of the same math, keyed by the data-source/data-target/
   data-*-handle/data-edge-type attributes below — keep those in sync with flow.js. *@

<svg data-slot="flow-edges"
     aria-hidden="true"
     class="@Cx.Merge("lumeo-flow-edges", Class)"
     style="position:absolute;left:0;top:0;width:1px;height:1px;overflow:visible;pointer-events:none;"
     @attributes="AdditionalAttributes">
    @if (Context is not null)
    {
        @foreach (var (edge, path) in Context.Canvas.RenderableEdges())
        {
            <path @key="edge.Id"
                  data-flow-edge
                  data-edge-id="@edge.Id"
                  data-source="@edge.Source"
                  data-target="@edge.Target"
                  data-source-handle="@edge.SourceHandle"
                  data-target-handle="@edge.TargetHandle"
                  data-edge-type="@FlowGeometry.FormatEdgeType(edge.Type)"
                  d="@path.D"
                  fill="none"
                  stroke="var(--color-border)" />
        }
    }
</svg>

@code {
    [CascadingParameter] private FlowCanvas.FlowCanvasContext? Context { get; set; }

    /// <summary>Additional CSS classes merged onto the edge layer's <c>&lt;svg&gt;</c>.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the edge layer's <c>&lt;svg&gt;</c>.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }
}

using System.Globalization;
using System.Text;

namespace Lumeo;

/// <summary>
/// Pure flow-canvas math: coordinate transforms, snapping, fit-view and the four edge path
/// generators. No DOM, no state — every member is a function of its arguments.
/// </summary>
/// <remarks>
/// <b>Lockstep with <c>flow.js</c>.</b> The engine rewrites edge paths live while a node is
/// dragged, with its own JavaScript port of <see cref="GetEdgePath"/>; the next Blazor render then
/// writes the path this class produces. The two must agree to the character or an edge visibly
/// twitches on drop. <c>FlowGeometryLockstepTests</c> compares this class against a table the JS
/// functions produce (<c>tests/js/flow-geometry-table.mjs</c>) — change both sides together and
/// regenerate the table.
/// </remarks>
public static class FlowGeometry
{
    /// <summary>Size used for a node that has neither a fixed size nor a measurement yet.</summary>
    public const double DefaultNodeWidth = 150;

    /// <summary>Size used for a node that has neither a fixed size nor a measurement yet.</summary>
    public const double DefaultNodeHeight = 40;

    /// <summary>The factor <c>ZoomInAsync</c>/<c>ZoomOutAsync</c> multiply/divide by.</summary>
    public const double ZoomStep = 1.2;

    /// <summary>How far a step/smooth-step route runs straight out of a handle before turning.</summary>
    public const double StepOffset = 20;

    /// <summary>Corner radius of a smooth-step route.</summary>
    public const double SmoothStepRadius = 5;

    /// <summary>Control-point curvature for a Bézier whose target lies behind its source.</summary>
    public const double BezierCurvature = 0.25;

    // ── Coordinate spaces ────────────────────────────────────────────────

    /// <summary>
    /// Pane-local pixels (relative to the pane's top-left corner) → flow coordinates:
    /// <c>(local - viewport.XY) / viewport.Zoom</c>.
    /// </summary>
    public static FlowPoint ScreenToFlow(double x, double y, FlowViewport viewport)
    {
        var zoom = viewport.Zoom > 0 ? viewport.Zoom : 1;
        return new FlowPoint((x - viewport.X) / zoom, (y - viewport.Y) / zoom);
    }

    /// <summary>Flow coordinates → pane-local pixels: <c>flow * viewport.Zoom + viewport.XY</c>.</summary>
    public static FlowPoint FlowToScreen(double x, double y, FlowViewport viewport)
    {
        var zoom = viewport.Zoom > 0 ? viewport.Zoom : 1;
        return new FlowPoint(x * zoom + viewport.X, y * zoom + viewport.Y);
    }

    /// <summary>Clamps <paramref name="zoom"/> into <c>[min, max]</c> (a max below min collapses to min).</summary>
    public static double ClampZoom(double zoom, double min, double max)
    {
        if (max < min) max = min;
        if (double.IsNaN(zoom)) return min;
        return Math.Min(max, Math.Max(min, zoom));
    }

    /// <summary>
    /// Re-scales <paramref name="viewport"/> to <paramref name="zoom"/> while keeping the flow point
    /// under the pane-local anchor exactly where it is — the pointer-anchored wheel zoom.
    /// </summary>
    public static FlowViewport ZoomAt(FlowViewport viewport, double zoom, double anchorX, double anchorY)
    {
        var p = ScreenToFlow(anchorX, anchorY, viewport);
        return new FlowViewport(anchorX - p.X * zoom, anchorY - p.Y * zoom, zoom);
    }

    /// <summary>
    /// A viewport that shows flow point (<paramref name="x"/>, <paramref name="y"/>) at the centre of
    /// a pane of the given size.
    /// </summary>
    public static FlowViewport CenterOn(double x, double y, double zoom, double paneWidth, double paneHeight)
        => new(paneWidth / 2 - x * zoom, paneHeight / 2 - y * zoom, zoom);

    // ── Snapping ─────────────────────────────────────────────────────────

    /// <summary>
    /// Rounds <paramref name="value"/> to the nearest multiple of <paramref name="grid"/> (ties round
    /// up, like JavaScript's <c>Math.round</c> — the engine snaps with the same rule). A grid of 0 or
    /// less returns the value unchanged.
    /// </summary>
    public static double Snap(double value, double grid)
        => grid > 0 ? Math.Floor(value / grid + 0.5) * grid : value;

    /// <summary>Snaps both axes of a point.</summary>
    public static FlowPoint Snap(FlowPoint point, double gridX, double gridY)
        => new(Snap(point.X, gridX), Snap(point.Y, gridY));

    // ── Bounds and fit-view ──────────────────────────────────────────────

    /// <summary>The union of <paramref name="rects"/>, or <c>null</c> when there are none.</summary>
    public static FlowRect? GetBounds(IEnumerable<FlowRect> rects)
    {
        ArgumentNullException.ThrowIfNull(rects);
        double minX = double.PositiveInfinity, minY = double.PositiveInfinity;
        double maxX = double.NegativeInfinity, maxY = double.NegativeInfinity;
        var any = false;
        foreach (var r in rects)
        {
            any = true;
            minX = Math.Min(minX, r.X);
            minY = Math.Min(minY, r.Y);
            maxX = Math.Max(maxX, r.X + r.Width);
            maxY = Math.Max(maxY, r.Y + r.Height);
        }
        return any ? new FlowRect(minX, minY, maxX - minX, maxY - minY) : null;
    }

    /// <summary>
    /// The viewport that fits every rect into a pane of the given size, centred.
    /// <paramref name="padding"/> is a fraction of the bounds (0.1 = 10% breathing room in total);
    /// the zoom is clamped to <c>[minZoom, maxZoom]</c>. Returns <c>null</c> when there is nothing to
    /// fit or the pane has no size yet.
    /// </summary>
    public static FlowViewport? FitView(IEnumerable<FlowRect> rects, double paneWidth, double paneHeight,
        double padding, double minZoom, double maxZoom)
    {
        var bounds = GetBounds(rects);
        if (bounds is not { } b || !(paneWidth > 0) || !(paneHeight > 0)) return null;
        var pad = padding > 0 ? padding : 0;
        var bw = Math.Max(b.Width, 1);
        var bh = Math.Max(b.Height, 1);
        var xZoom = paneWidth / (bw * (1 + pad));
        var yZoom = paneHeight / (bh * (1 + pad));
        var zoom = ClampZoom(Math.Min(xZoom, yZoom), minZoom, maxZoom);
        var cx = b.X + b.Width / 2;
        var cy = b.Y + b.Height / 2;
        return CenterOn(cx, cy, zoom, paneWidth, paneHeight);
    }

    // ── Handles ──────────────────────────────────────────────────────────

    /// <summary>
    /// The default anchor on a node's side — the midpoint of that edge. Used when the node renders
    /// no matching <see cref="FlowHandle"/> (or it has not been measured yet).
    /// </summary>
    public static FlowPoint GetHandleAnchor(FlowRect node, FlowPosition position) => position switch
    {
        FlowPosition.Left => new(node.X, node.Y + node.Height / 2),
        FlowPosition.Right => new(node.X + node.Width, node.Y + node.Height / 2),
        FlowPosition.Top => new(node.X + node.Width / 2, node.Y),
        _ => new(node.X + node.Width / 2, node.Y + node.Height),
    };

    // ── Edge paths ───────────────────────────────────────────────────────

    /// <summary>Dispatches to the generator for <paramref name="type"/>.</summary>
    public static FlowEdgePath GetEdgePath(FlowEdgeType type,
        double sourceX, double sourceY, FlowPosition sourcePosition,
        double targetX, double targetY, FlowPosition targetPosition) => type switch
    {
        FlowEdgeType.Straight => GetStraightPath(sourceX, sourceY, targetX, targetY),
        FlowEdgeType.Step => GetStepPath(sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition),
        FlowEdgeType.SmoothStep => GetSmoothStepPath(sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition),
        _ => GetBezierPath(sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition),
    };

    /// <summary>A straight line; the label sits at its midpoint.</summary>
    public static FlowEdgePath GetStraightPath(double sourceX, double sourceY, double targetX, double targetY)
    {
        var d = "M" + Fmt(sourceX) + "," + Fmt(sourceY) + " L" + Fmt(targetX) + "," + Fmt(targetY);
        return new FlowEdgePath(d, (sourceX + targetX) / 2, (sourceY + targetY) / 2);
    }

    /// <summary>
    /// A cubic Bézier whose control points run out of each anchor along its handle's direction —
    /// half the anchor distance when the other end lies ahead, a curvature-scaled loop when it lies
    /// behind. The label sits on the curve at t = 0.5.
    /// </summary>
    public static FlowEdgePath GetBezierPath(double sourceX, double sourceY, FlowPosition sourcePosition,
        double targetX, double targetY, FlowPosition targetPosition)
    {
        var (c1x, c1y) = ControlPoint(sourcePosition, sourceX, sourceY, targetX, targetY);
        var (c2x, c2y) = ControlPoint(targetPosition, targetX, targetY, sourceX, sourceY);
        var d = "M" + Fmt(sourceX) + "," + Fmt(sourceY)
              + " C" + Fmt(c1x) + "," + Fmt(c1y)
              + " " + Fmt(c2x) + "," + Fmt(c2y)
              + " " + Fmt(targetX) + "," + Fmt(targetY);
        var lx = sourceX * 0.125 + c1x * 0.375 + c2x * 0.375 + targetX * 0.125;
        var ly = sourceY * 0.125 + c1y * 0.375 + c2y * 0.375 + targetY * 0.125;
        return new FlowEdgePath(d, lx, ly);
    }

    /// <summary>An orthogonal route with sharp corners (a smooth-step with radius 0).</summary>
    public static FlowEdgePath GetStepPath(double sourceX, double sourceY, FlowPosition sourcePosition,
        double targetX, double targetY, FlowPosition targetPosition)
        => GetSmoothStepPath(sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition, 0, StepOffset);

    /// <summary>
    /// An orthogonal route: straight out of the source handle by <paramref name="offset"/>, across,
    /// and straight into the target handle, every corner rounded by up to
    /// <paramref name="borderRadius"/>. The label sits halfway along the route.
    /// </summary>
    public static FlowEdgePath GetSmoothStepPath(double sourceX, double sourceY, FlowPosition sourcePosition,
        double targetX, double targetY, FlowPosition targetPosition,
        double borderRadius = SmoothStepRadius, double offset = StepOffset)
    {
        var pts = StepPoints(sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition, offset);

        var sb = new StringBuilder();
        sb.Append('M').Append(Fmt(pts[0].X)).Append(',').Append(Fmt(pts[0].Y));
        for (var i = 1; i < pts.Count - 1; i++)
        {
            var a = pts[i - 1];
            var b = pts[i];
            var c = pts[i + 1];
            var lab = Dist(a, b);
            var lbc = Dist(b, c);
            var r = Math.Min(borderRadius, Math.Min(lab / 2, lbc / 2));
            if (r > 0 && lab > 0 && lbc > 0)
            {
                var inX = b.X - (b.X - a.X) / lab * r;
                var inY = b.Y - (b.Y - a.Y) / lab * r;
                var outX = b.X + (c.X - b.X) / lbc * r;
                var outY = b.Y + (c.Y - b.Y) / lbc * r;
                sb.Append(" L").Append(Fmt(inX)).Append(',').Append(Fmt(inY));
                sb.Append(" Q").Append(Fmt(b.X)).Append(',').Append(Fmt(b.Y));
                sb.Append(' ').Append(Fmt(outX)).Append(',').Append(Fmt(outY));
            }
            else
            {
                sb.Append(" L").Append(Fmt(b.X)).Append(',').Append(Fmt(b.Y));
            }
        }
        var last = pts[^1];
        sb.Append(" L").Append(Fmt(last.X)).Append(',').Append(Fmt(last.Y));

        var (lx, ly) = PolylineMidpoint(pts);
        return new FlowEdgePath(sb.ToString(), lx, ly);
    }

    /// <summary>
    /// The corner points of an orthogonal route (source anchor, offset point, turns, target offset
    /// point, target anchor), with duplicates and straight-through points removed.
    /// </summary>
    internal static List<FlowPoint> StepPoints(double sx, double sy, FlowPosition sPos,
        double tx, double ty, FlowPosition tPos, double offset)
    {
        var (sdx, sdy) = Direction(sPos);
        var (tdx, tdy) = Direction(tPos);
        var s0 = new FlowPoint(sx, sy);
        var t0 = new FlowPoint(tx, ty);
        var s1 = new FlowPoint(sx + sdx * offset, sy + sdy * offset);
        var t1 = new FlowPoint(tx + tdx * offset, ty + tdy * offset);
        var sH = sPos is FlowPosition.Left or FlowPosition.Right;
        var tH = tPos is FlowPosition.Left or FlowPosition.Right;

        var raw = new List<FlowPoint> { s0, s1 };
        if (sH && tH)
        {
            if (sPos == tPos)
            {
                // Both handles face the same way: run out to whichever offset point is further along.
                var ex = sdx > 0 ? Math.Max(s1.X, t1.X) : Math.Min(s1.X, t1.X);
                raw.Add(new FlowPoint(ex, s1.Y));
                raw.Add(new FlowPoint(ex, t1.Y));
            }
            else if (sdx * (t1.X - s1.X) >= 0)
            {
                var mx = (s1.X + t1.X) / 2;
                raw.Add(new FlowPoint(mx, s1.Y));
                raw.Add(new FlowPoint(mx, t1.Y));
            }
            else
            {
                // Target lies behind the source: cross over halfway between the two rows instead.
                var my = (s1.Y + t1.Y) / 2;
                raw.Add(new FlowPoint(s1.X, my));
                raw.Add(new FlowPoint(t1.X, my));
            }
        }
        else if (!sH && !tH)
        {
            if (sPos == tPos)
            {
                var ey = sdy > 0 ? Math.Max(s1.Y, t1.Y) : Math.Min(s1.Y, t1.Y);
                raw.Add(new FlowPoint(s1.X, ey));
                raw.Add(new FlowPoint(t1.X, ey));
            }
            else if (sdy * (t1.Y - s1.Y) >= 0)
            {
                var my = (s1.Y + t1.Y) / 2;
                raw.Add(new FlowPoint(s1.X, my));
                raw.Add(new FlowPoint(t1.X, my));
            }
            else
            {
                var mx = (s1.X + t1.X) / 2;
                raw.Add(new FlowPoint(mx, s1.Y));
                raw.Add(new FlowPoint(mx, t1.Y));
            }
        }
        else if (sH)
        {
            raw.Add(new FlowPoint(t1.X, s1.Y));
        }
        else
        {
            raw.Add(new FlowPoint(s1.X, t1.Y));
        }
        raw.Add(t1);
        raw.Add(t0);

        // Drop repeated points, then points a straight segment merely passes through (same
        // direction on both sides). A reversal is kept: removing it would change the route.
        var dedup = new List<FlowPoint>(raw.Count);
        foreach (var p in raw)
        {
            if (dedup.Count > 0 && Same(dedup[^1], p)) continue;
            dedup.Add(p);
        }
        var result = new List<FlowPoint>(dedup.Count);
        for (var i = 0; i < dedup.Count; i++)
        {
            if (i > 0 && i < dedup.Count - 1)
            {
                var a = result[^1];
                var b = dedup[i];
                var c = dedup[i + 1];
                var cross = (b.X - a.X) * (c.Y - b.Y) - (b.Y - a.Y) * (c.X - b.X);
                var dot = (b.X - a.X) * (c.X - b.X) + (b.Y - a.Y) * (c.Y - b.Y);
                if (Math.Abs(cross) < 1e-9 && dot >= 0) continue;
            }
            result.Add(dedup[i]);
        }
        return result;
    }

    private static (double X, double Y) PolylineMidpoint(List<FlowPoint> pts)
    {
        var total = 0.0;
        for (var i = 1; i < pts.Count; i++) total += Dist(pts[i - 1], pts[i]);
        if (total <= 0) return (pts[0].X, pts[0].Y);
        var half = total / 2;
        var walked = 0.0;
        for (var i = 1; i < pts.Count; i++)
        {
            var seg = Dist(pts[i - 1], pts[i]);
            if (walked + seg >= half && seg > 0)
            {
                var t = (half - walked) / seg;
                return (pts[i - 1].X + (pts[i].X - pts[i - 1].X) * t, pts[i - 1].Y + (pts[i].Y - pts[i - 1].Y) * t);
            }
            walked += seg;
        }
        return (pts[^1].X, pts[^1].Y);
    }

    private static (double X, double Y) ControlPoint(FlowPosition position, double x1, double y1, double x2, double y2) => position switch
    {
        FlowPosition.Left => (x1 - ControlOffset(x1 - x2), y1),
        FlowPosition.Right => (x1 + ControlOffset(x2 - x1), y1),
        FlowPosition.Top => (x1, y1 - ControlOffset(y1 - y2)),
        _ => (x1, y1 + ControlOffset(y2 - y1)),
    };

    private static double ControlOffset(double distance)
        => distance >= 0 ? 0.5 * distance : BezierCurvature * 25 * Math.Sqrt(-distance);

    private static (double X, double Y) Direction(FlowPosition position) => position switch
    {
        FlowPosition.Left => (-1, 0),
        FlowPosition.Right => (1, 0),
        FlowPosition.Top => (0, -1),
        _ => (0, 1),
    };

    private static double Dist(FlowPoint a, FlowPoint b)
    {
        var dx = b.X - a.X;
        var dy = b.Y - a.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }

    private static bool Same(FlowPoint a, FlowPoint b) => Math.Abs(a.X - b.X) < 1e-9 && Math.Abs(a.Y - b.Y) < 1e-9;

    /// <summary>
    /// Formats a coordinate the way <c>flow.js</c> does: rounded to 3 decimals with
    /// <c>floor(v * 1000 + 0.5) / 1000</c> (JavaScript's <c>Math.round</c>), culture-invariant, shortest
    /// round-trip digits, and never "-0".
    /// </summary>
    internal static string Fmt(double value)
    {
        if (!double.IsFinite(value)) return "0";
        var r = Math.Floor(value * 1000 + 0.5) / 1000;
        if (r == 0) r = 0; // normalises -0
        return r.ToString("R", CultureInfo.InvariantCulture);
    }

    internal static string FormatPosition(FlowPosition position) => position switch
    {
        FlowPosition.Left => "left",
        FlowPosition.Right => "right",
        FlowPosition.Top => "top",
        _ => "bottom",
    };

    internal static FlowPosition? ParsePosition(string? value) => value switch
    {
        "left" => FlowPosition.Left,
        "right" => FlowPosition.Right,
        "top" => FlowPosition.Top,
        "bottom" => FlowPosition.Bottom,
        _ => null,
    };

    internal static string FormatEdgeType(FlowEdgeType type) => type switch
    {
        FlowEdgeType.SmoothStep => "smoothstep",
        FlowEdgeType.Step => "step",
        FlowEdgeType.Straight => "straight",
        _ => "bezier",
    };
}

