@code {
    [CascadingParameter] private FlowCanvas.FlowCanvasContext? Context { get; set; }

    /// <summary>The node this host positions and wraps.</summary>
    [Parameter, EditorRequired] public FlowNode Node { get; set; } = default!;

    /// <summary>Additional CSS classes merged onto the host element.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the host element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private FlowCanvas? Canvas => Context?.Canvas;
    private bool Selected => Canvas?.IsSelected(Node.Id) == true;
    private bool Dragging => Canvas?.IsDragging(Node.Id) == true;
    private bool Draggable => Canvas?.CanDrag(Node) == true;

    private string HostClass => Cx.Merge("lumeo-flow-node", Class);

    private string HostStyle
    {
        get
        {
            var style = "position:absolute;left:0;top:0;transform:translate(" + FlowCanvas.R(Node.X) + "px, " + FlowCanvas.R(Node.Y) + "px);";
            if (Node.Width is { } w) style += "width:" + FlowCanvas.R(w) + "px;";
            if (Node.Height is { } h) style += "height:" + FlowCanvas.R(h) + "px;";
            if (Node.ZIndex is { } z) style += "z-index:" + z.ToString(System.Globalization.CultureInfo.InvariantCulture) + ";";
            return style;
        }
    }

    private Task HandleClickAsync() => Canvas?.HandleNodeClickAsync(Node) ?? Task.CompletedTask;
    private Task HandleDoubleClickAsync() => Canvas?.HandleNodeDoubleClickAsync(Node) ?? Task.CompletedTask;
    private Task HandleContextMenuAsync(MouseEventArgs e) => Canvas?.HandleNodeContextMenuAsync(Node, e) ?? Task.CompletedTask;
    private Task HandleKeyDownAsync(KeyboardEventArgs e) => Canvas?.HandleNodeKeyDownAsync(Node, e) ?? Task.CompletedTask;
}

namespace Lumeo;

/// <summary>
/// A FlowCanvas' non-render state: the latest known viewport, the viewport .NET last asked the
/// engine to apply (the stamp), measured node sizes and handle offsets, the pane size, the current
/// selection and the node-list generation. No render-loop coupling — the canvas decides when to
/// render; this class only answers questions.
/// </summary>
internal sealed class FlowState
{
    private readonly Dictionary<string, Measured> _measured = new(StringComparer.Ordinal);
    private readonly Queue<FlowViewport> _recentReports = new();

    private sealed record Measured(double Width, double Height, IReadOnlyList<HandleInfo> Handles);

    /// <summary>A measured handle: centre offset from the node's top-left, in flow units.</summary>
    internal sealed record HandleInfo(string? Id, FlowHandleType Type, FlowPosition Position, double X, double Y);

    /// <summary>The latest viewport known to .NET — engine reports or .NET-originated sets.</summary>
    public FlowViewport Viewport { get; private set; } = new(0, 0, 1);

    /// <summary>The viewport of the latest .NET-originated set (what the stamp carries).</summary>
    public FlowViewport StampedViewport { get; private set; } = new(0, 0, 1);

    /// <summary>Monotonic id of the latest .NET-originated viewport set; 0 = the initial viewport.</summary>
    public long StampId { get; private set; }

    /// <summary>
    /// Bumped whenever the node list is replaced from OUTSIDE (not an echo of the canvas' own
    /// commit). A drag that started under an older generation is stale and never committed.
    /// </summary>
    public int Generation { get; private set; }

    public double PaneWidth { get; private set; }
    public double PaneHeight { get; private set; }

    public HashSet<string> SelectedNodeIds { get; } = new(StringComparer.Ordinal);
    public HashSet<string> DraggingNodeIds { get; } = new(StringComparer.Ordinal);

    public void Initialize(FlowViewport viewport)
    {
        Viewport = viewport;
        StampedViewport = viewport;
    }

    /// <summary>A .NET-originated viewport change: recorded and given a fresh stamp id.</summary>
    public void Stamp(FlowViewport viewport)
    {
        Viewport = viewport;
        StampedViewport = viewport;
        StampId++;
    }

    /// <summary>
    /// The engine reported <paramref name="viewport"/>. Remembered for echo detection: a bound
    /// <c>Viewport</c> parameter that comes back with a value the engine itself reported is not a
    /// new instruction.
    /// </summary>
    public void Report(FlowViewport viewport)
    {
        Viewport = viewport;
        _recentReports.Enqueue(viewport);
        while (_recentReports.Count > 16) _recentReports.Dequeue();
    }

    public bool IsEcho(FlowViewport viewport) => viewport == Viewport || _recentReports.Contains(viewport);

    public void BumpGeneration() => Generation++;

    public void SetPaneSize(double width, double height)
    {
        PaneWidth = width > 0 ? width : 0;
        PaneHeight = height > 0 ? height : 0;
    }

    /// <summary>Applies an engine measurement batch; returns true when anything changed.</summary>
    public bool ApplyMeasurements(IEnumerable<FlowNodeMeasurement> measurements)
    {
        var changed = false;
        foreach (var m in measurements)
        {
            if (m is null || string.IsNullOrEmpty(m.Id)) continue;
            var handles = new List<HandleInfo>();
            if (m.Handles is not null)
            {
                foreach (var h in m.Handles)
                {
                    if (h is null) continue;
                    var type = string.Equals(h.Type, "target", StringComparison.OrdinalIgnoreCase) ? FlowHandleType.Target : FlowHandleType.Source;
                    var pos = FlowGeometry.ParsePosition(h.Position?.ToLowerInvariant())
                              ?? (type == FlowHandleType.Source ? FlowPosition.Right : FlowPosition.Left);
                    handles.Add(new HandleInfo(string.IsNullOrEmpty(h.Id) ? null : h.Id, type, pos, h.X, h.Y));
                }
            }
            var next = new Measured(m.Width, m.Height, handles);
            if (_measured.TryGetValue(m.Id, out var prev)
                && prev.Width == next.Width && prev.Height == next.Height
                && prev.Handles.SequenceEqual(next.Handles))
            {
                continue;
            }
            _measured[m.Id] = next;
            changed = true;
        }
        return changed;
    }

    public void ForgetMissing(IEnumerable<FlowNode> nodes)
    {
        if (_measured.Count == 0) return;
        var live = new HashSet<string>(nodes.Select(n => n.Id), StringComparer.Ordinal);
        foreach (var id in _measured.Keys.Where(id => !live.Contains(id)).ToList()) _measured.Remove(id);
    }

    public bool IsMeasured(string id) => _measured.ContainsKey(id);

    /// <summary>The node's rect: fixed size &gt; measured size &gt; <see cref="FlowGeometry.DefaultNodeWidth"/>.</summary>
    public FlowRect GetNodeRect(FlowNode node)
    {
        _measured.TryGetValue(node.Id, out var m);
        var w = node.Width ?? m?.Width ?? FlowGeometry.DefaultNodeWidth;
        var h = node.Height ?? m?.Height ?? FlowGeometry.DefaultNodeHeight;
        return new FlowRect(node.X, node.Y, w, h);
    }

    /// <summary>
    /// Where an edge attaches: the handle with <paramref name="handleId"/> (or the node's first
    /// handle of <paramref name="type"/> when the id is null), else the default side — right for a
    /// source, left for a target. Mirrors <c>anchorFor</c> in flow.js.
    /// </summary>
    public (FlowPoint Point, FlowPosition Position) GetAnchor(FlowNode node, string? handleId, FlowHandleType type)
    {
        var rect = GetNodeRect(node);
        if (_measured.TryGetValue(node.Id, out var m) && m.Handles.Count > 0)
        {
            HandleInfo? match = null;
            foreach (var h in m.Handles)
            {
                if (h.Type != type) continue;
                if (handleId is null || string.Equals(h.Id, handleId, StringComparison.Ordinal))
                {
                    match = h;
                    break;
                }
            }
            if (match is not null)
            {
                return (new FlowPoint(node.X + match.X, node.Y + match.Y), match.Position);
            }
        }
        var side = type == FlowHandleType.Source ? FlowPosition.Right : FlowPosition.Left;
        return (FlowGeometry.GetHandleAnchor(rect, side), side);
    }

    /// <summary>The viewport that fits <paramref name="nodes"/> into the pane, or null when not computable.</summary>
    public FlowViewport? ComputeFit(IReadOnlyList<FlowNode> nodes, double padding, double minZoom, double maxZoom)
        => FlowGeometry.FitView(nodes.Select(GetNodeRect), PaneWidth, PaneHeight, padding, minZoom, maxZoom);

    /// <summary>True when every node has a fixed size or a measurement — a .NET-side fit is exact.</summary>
    public bool AllSized(IReadOnlyList<FlowNode> nodes)
        => nodes.All(n => (n.Width is not null && n.Height is not null) || _measured.ContainsKey(n.Id));
}

using System.ComponentModel;

namespace Lumeo;

/// <summary>Whether a <see cref="FlowHandle"/> starts connections (<see cref="Source"/>) or accepts them (<see cref="Target"/>).</summary>
public enum FlowHandleType
{
    /// <summary>An outgoing port — edges start here.</summary>
    Source,
    /// <summary>An incoming port — edges end here.</summary>
    Target,
}

/// <summary>
/// The PHYSICAL side of a node a handle sits on, and the direction an edge leaves/enters it.
/// Physical, not logical: <see cref="Left"/> stays left under <c>dir="rtl"</c> (the canvas is a
/// geometric surface, not a text flow).
/// </summary>
public enum FlowPosition
{
    /// <summary>The node's left edge.</summary>
    Left,
    /// <summary>The node's right edge.</summary>
    Right,
    /// <summary>The node's top edge.</summary>
    Top,
    /// <summary>The node's bottom edge.</summary>
    Bottom,
}

/// <summary>How an edge's path is routed between its two anchors.</summary>
public enum FlowEdgeType
{
    /// <summary>A cubic Bézier that leaves/enters each anchor along its handle's direction.</summary>
    Bezier,
    /// <summary>An orthogonal route with rounded corners.</summary>
    SmoothStep,
    /// <summary>An orthogonal route with sharp corners.</summary>
    Step,
    /// <summary>A straight line.</summary>
    Straight,
}

/// <summary>The pattern <see cref="FlowBackground"/> draws.</summary>
public enum FlowBackgroundVariant
{
    /// <summary>A dot at every grid intersection.</summary>
    Dots,
    /// <summary>Continuous grid lines.</summary>
    Lines,
    /// <summary>A small cross at every grid intersection.</summary>
    Cross,
}

/// <summary>
/// One node on a <see cref="FlowCanvas"/>. Immutable — update with <c>with</c>, the canvas emits a
/// new list through <c>NodesChanged</c> on every committed move.
/// </summary>
/// <param name="Id">Stable identifier; edges reference nodes by it.</param>
/// <param name="X">Left edge in flow coordinates.</param>
/// <param name="Y">Top edge in flow coordinates.</param>
/// <param name="Type">Your own discriminator for <c>NodeTemplate</c> (e.g. "trigger", "action").</param>
/// <param name="Data">Arbitrary payload for the template.</param>
/// <param name="Width">Fixed width in flow units; <c>null</c> = sized by its content and measured.</param>
/// <param name="Height">Fixed height in flow units; <c>null</c> = sized by its content and measured.</param>
/// <param name="Draggable">Per-node drag switch (ANDed with the canvas' own switches).</param>
/// <param name="Selectable">Per-node selection switch.</param>
/// <param name="Connectable">Per-node connect switch (phase 2).</param>
/// <param name="Deletable">Per-node delete switch (phase 2).</param>
/// <param name="ZIndex">Explicit stacking order; <c>null</c> = document order.</param>
public sealed record FlowNode(
    string Id, double X, double Y,
    string? Type = null,
    object? Data = null,
    double? Width = null, double? Height = null,
    bool Draggable = true, bool Selectable = true, bool Connectable = true,
    bool Deletable = true, int? ZIndex = null);

/// <summary>An edge between two nodes, drawn as one SVG path.</summary>
/// <param name="Id">Stable identifier.</param>
/// <param name="Source">The source node's <see cref="FlowNode.Id"/>.</param>
/// <param name="Target">The target node's <see cref="FlowNode.Id"/>.</param>
/// <param name="SourceHandle">The source <see cref="FlowHandle"/>'s <c>Id</c>; <c>null</c> = the node's first source handle, or its right edge.</param>
/// <param name="TargetHandle">The target <see cref="FlowHandle"/>'s <c>Id</c>; <c>null</c> = the node's first target handle, or its left edge.</param>
/// <param name="Label">Optional label (rendered from phase 2).</param>
/// <param name="Type">Path routing.</param>
/// <param name="Animated">Dash animation (phase 2).</param>
/// <param name="Dashed">Dashed stroke (phase 2).</param>
/// <param name="Deletable">Per-edge delete switch (phase 2).</param>
/// <param name="MarkerEnd">End marker id (phase 2).</param>
/// <param name="Data">Arbitrary payload.</param>
public sealed record FlowEdge(
    string Id, string Source, string Target,
    string? SourceHandle = null, string? TargetHandle = null,
    string? Label = null, FlowEdgeType Type = FlowEdgeType.Bezier,
    bool Animated = false, bool Dashed = false, bool Deletable = true,
    string? MarkerEnd = "arrow", object? Data = null);

/// <summary>
/// The pan/zoom state: a flow point <c>p</c> is drawn at pane-local <c>p * Zoom + (X, Y)</c>.
/// </summary>
/// <param name="X">Horizontal translation in pane pixels.</param>
/// <param name="Y">Vertical translation in pane pixels.</param>
/// <param name="Zoom">Scale factor (1 = 100%).</param>
public readonly record struct FlowViewport(double X, double Y, double Zoom);

/// <summary>A point, in whichever space the member that returns it documents.</summary>
public readonly record struct FlowPoint(double X, double Y);

/// <summary>An axis-aligned rectangle in flow coordinates.</summary>
public readonly record struct FlowRect(double X, double Y, double Width, double Height)
{
    /// <summary>The right edge.</summary>
    public double Right => X + Width;
    /// <summary>The bottom edge.</summary>
    public double Bottom => Y + Height;
}

/// <summary>A generated edge path plus the point its label is centred on.</summary>
/// <param name="D">The SVG path data (culture-invariant, 3 decimals).</param>
/// <param name="LabelX">Label anchor X in flow coordinates.</param>
/// <param name="LabelY">Label anchor Y in flow coordinates.</param>
public readonly record struct FlowEdgePath(string D, double LabelX, double LabelY);

/// <summary>A new connection proposed by dragging between two handles (phase 2).</summary>
public sealed record FlowConnection(string Source, string? SourceHandle, string Target, string? TargetHandle);

/// <summary>One node's committed position after a drag or keyboard move.</summary>
/// <param name="Id">The node's id.</param>
/// <param name="X">New left edge in flow coordinates.</param>
/// <param name="Y">New top edge in flow coordinates.</param>
public sealed record FlowNodeChange(string Id, double X, double Y);

/// <summary>The selected node and edge ids.</summary>
public sealed record FlowSelection(IReadOnlySet<string> NodeIds, IReadOnlySet<string> EdgeIds);

/// <summary>What <c>NodeTemplate</c> receives for each node.</summary>
/// <param name="Node">The node being rendered.</param>
/// <param name="Selected">The node is selected.</param>
/// <param name="Dragging">A pointer drag is moving the node right now.</param>
/// <param name="Canvas">The owning canvas (for its imperative methods).</param>
public sealed record FlowNodeContext(FlowNode Node, bool Selected, bool Dragging, FlowCanvas Canvas);

/// <summary>What an edge label template receives (phase 2).</summary>
public sealed record FlowEdgeContext(FlowEdge Edge, bool Selected, double LabelX, double LabelY);

/// <summary>Arguments for <c>FlowCanvas.OnNodeContextMenu</c>.</summary>
/// <param name="Node">The node that was right-clicked.</param>
/// <param name="ClientX">Pointer X in viewport (client) pixels — ready for positioning a menu.</param>
/// <param name="ClientY">Pointer Y in viewport (client) pixels.</param>
public sealed record FlowNodeContextMenuEventArgs(FlowNode Node, double ClientX, double ClientY);

/// <summary>
/// Interop payload: one node's measured size and its handles, reported by the engine.
/// Not meant for application code.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed record FlowNodeMeasurement(string Id, double Width, double Height, FlowHandleMeasurement[]? Handles);

/// <summary>
/// Interop payload: a handle's centre relative to its node's top-left corner, in flow units.
/// <paramref name="Type"/> is "source"/"target", <paramref name="Position"/> "left"/"right"/"top"/"bottom".
/// Not meant for application code.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed record FlowHandleMeasurement(string? Id, string Type, string Position, double X, double Y);
